### Objective
Build a production-grade End-to-End Checkout & Integration Test Simulator in Flutter. The application demonstrates real-world E2E testing concepts: multi-screen navigation flows from catalog to checkout, interacting with native simulated permissions (Location/Camera), measuring transaction execution time, and an interactive test runner displaying integration test trace steps.

```dart
import 'package:flutter/material.dart';

void main() {
  runApp(const IntegrationMasterclassApp());
}

class IntegrationMasterclassApp extends StatelessWidget {
  const IntegrationMasterclassApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Integration Testing & Patrol',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.teal,
        useMaterial3: true,
      ),
      home: const E2ETestHarnessScreen(),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. PRODUCTION APP FLOW: CHECKOUT SYSTEM
// ─────────────────────────────────────────────────────────────────────────────

class E2ECheckoutFlow extends StatefulWidget {
  final VoidCallback onOrderCompleted;

  const E2ECheckoutFlow({super.key, required this.onOrderCompleted});

  @override
  State<E2ECheckoutFlow> createState() => _E2ECheckoutFlowState();
}

class _E2ECheckoutFlowState extends State<E2ECheckoutFlow> {
  int _step = 0; // 0: Catalog, 1: Native Permission, 2: Payment, 3: Completed
  bool _hasLocationPermission = false;
  String _selectedPaymentMethod = 'Apple Pay / Google Pay';

  @override
  Widget build(BuildContext context) {
    final colorScheme = Theme.of(context).colorScheme;

    return Card(
      elevation: 2,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
      child: Padding(
        padding: const EdgeInsets.all(20.0),
        child: AnimatedSwitcher(
          duration: const Duration(milliseconds: 300),
          child: _buildCurrentStep(colorScheme),
        ),
      ),
    );
  }

  Widget _buildCurrentStep(ColorScheme colorScheme) {
    switch (_step) {
      case 0:
        return Column(
          key: const Key('catalog_step'),
          crossAxisAlignment: CrossAxisAlignment.start,
          children:
 [
            Text('Order Summary', style: Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.bold)),
            const SizedBox(height: 12),
            ListTile(
              key: const Key('item_tile_pro_rig'),
              leading: CircleAvatar(backgroundColor: colorScheme.primaryContainer, child: const Icon(Icons.laptop_chromebook)),
              title: const Text('Impeller Hardware Dev Kit', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 14)),
              subtitle: const Text('1x Enterprise License • $1,299.00'),
              trailing: const Icon(Icons.check_circle, color: Colors.green),
              contentPadding: EdgeInsets.zero,
            ),
            const SizedBox(height: 16),
            FilledButton.icon(
              key: const Key('proceed_to_shipping_btn'),
              onPressed: () => setState(() => _step = 1),
              icon: const Icon(Icons.local_shipping_outlined),
              label: const Text('Proceed to Shipping Verification'),
            ),
          ],
        );
      case 1:
        return Column(
          key: const Key('permission_step'),
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text('Native Location Verification', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 15)),
            const SizedBox(height: 8),
            const Text('Verifies delivery jurisdiction via native OS permissions (Patrol automation target).', style: TextStyle(fontSize: 12, color: Colors.black54)),
            const SizedBox(height: 16),
            Container(
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: _hasLocationPermission ? Colors.green.shade50 : Colors.amber.shade50,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: _hasLocationPermission ? Colors.green : Colors.amber.shade700),
              ),
              child: Row(
                children: [
                  Icon(_hasLocationPermission ? Icons.verified_user : Icons.location_searching, color: _hasLocationPermission ? Colors.green : Colors.amber.shade800),
                  const SizedBox(width: 12),
                  Text(_hasLocationPermission ? 'Native Permission Granted' : 'Awaiting Native Authorization', style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 13)),
                ],
              ),
            ),
            const SizedBox(height: 16),
            Row(
              children: [
                FilledButton.tonal(
                  key: const Key('native_permission_btn'),
                  onPressed: () => setState(() => _hasLocationPermission = true),
                  child: const Text('Simulate Patrol Permission Tap'),
                ),
                const SizedBox(width: 12),
                FilledButton(
                  key: const Key('proceed_to_payment_btn'),
                  onPressed: _hasLocationPermission ? () => setState(() => _step = 2) : null,
                  child: const Text('Continue'),
                ),
              ],
            ),
          ],
        );
      case 2:
        return Column(
          key: const Key('payment_step'),
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text('Secure Payment Authorization', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 15)),
            const SizedBox(height: 12),
            RadioListTile<String>(
              key: const Key('radio_apple_pay'),
              title: const Text('Verified Biometric Pass (Apple/Google Pay)'),
              value: 'Apple Pay / Google Pay',
              groupValue: _selectedPaymentMethod,
              onChanged: (val) => setState(() => _selectedPaymentMethod = val!),
              contentPadding: EdgeInsets.zero,
            ),
            const SizedBox(height: 16),
            FilledButton.icon(
              key: const Key('authorize_transaction_btn'),
              onPressed: () {
                setState(() => _step = 3);
                widget.onOrderCompleted();
              },
              icon: const Icon(Icons.fingerprint_rounded),
              label: const Text('Authorize & Place Order'),
            ),
          ],
        );
      case 3:
      default:
        return Column(
          key: const Key('order_success_step'),
          children: [
            const Icon(Icons.check_circle_rounded, color: Colors.green, size: 64),
            const SizedBox(height: 12),
            const Text('Order #FL-88901 Placed!', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 18)),
            const SizedBox(height: 6),
            const Text('E2E integration test sequence executed and verified on native engine.', style: TextStyle(fontSize: 12, color: Colors.black54), textAlign: TextAlign.center),
            const SizedBox(height: 16),
            OutlinedButton(onPressed: () => setState(() => _step = 0), child: const Text('Reset Flow')),
          ],
        );
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. INTEGRATION TEST HARNESS SCREEN
// ─────────────────────────────────────────────────────────────────────────────

class E2ETestHarnessScreen extends StatefulWidget {
  const E2ETestHarnessScreen({super.key});

  @override
  State<E2ETestHarnessScreen> createState() => _E2ETestHarnessScreenState();
}

class _E2ETestHarnessScreenState extends State<E2ETestHarnessScreen> {
  final List<String> _traceLogs = [];
  bool _isRunningE2E = false;

  void _log(String msg) {
    setState(() => _traceLogs.add(msg));
  }

  Future<void> _runE2ETestSuite() async {
    setState(() {
      _isRunningE2E = true;
      _traceLogs.clear();
    });

    _log('🚀 [PATROL DRIVER] Launching real application process...');
    await Future.delayed(const Duration(milliseconds: 300));

    _log('📱 [STEP 1] app.main() initialized. Verified catalog items rendered.');
    await Future.delayed(const Duration(milliseconds: 350));

    _log('👆 [STEP 2] Tap: $(#proceed_to_shipping_btn) -> Navigating to shipping step.');
    await Future.delayed(const Duration(milliseconds: 300));

    _log('🛡️ [STEP 3] Patrol Native Automator: $.native.grantPermissionWhenInUse()');
    await Future.delayed(const Duration(milliseconds: 400));
    _log('✅ Native OS Location dialog accepted by system test runner.');

    _log('💳 [STEP 4] Tap: $(#authorize_transaction_btn) -> Executing payment.');
    await Future.delayed(const Duration(milliseconds: 350));

    _log('🎉 [STEP 5] E2E Assertion Passed: expect($("#order_success_step"), findsOneWidget)');
    _log('⏱️ Total Execution Time: 1.70s. 0 Frame drops, 0 Unhandled exceptions.');

    setState(() => _isRunningE2E = false);
  }

  @override
  Widget build(BuildContext context) {
    final colorScheme = Theme.of(context).colorScheme;

    return Scaffold(
      appBar: AppBar(
        title: const Text('End-to-End Integration Testing'),
        centerTitle: true,
      ),
      body: ListView(
        padding: const EdgeInsets.all(20),
        children: [
          // Interactive App Under Test
          E2ECheckoutFlow(onOrderCompleted: () {}),
          const SizedBox(height: 24),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              const Text('Patrol & E2E Test Execution', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 15)),
              FilledButton.icon(
                onPressed: _isRunningE2E ? null : _runE2ETestSuite,
                icon: _isRunningE2E
                    ? const SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                    : const Icon(Icons.play_circle_filled_rounded),
                label: Text(_isRunningE2E ? 'Testing E2E...' : 'Run Patrol E2E Suite'),
              ),
            ],
          ),
          const SizedBox(height: 12),
          Container(
            height: 220,
            padding: const EdgeInsets.all(14),
            decoration: BoxDecoration(
              color: const Color(0xFF0F172A),
              borderRadius: BorderRadius.circular(14),
              border: Border.all(color: Colors.white12),
            ),
            child: _traceLogs.isEmpty
                ? const Center(
                    child: Text('Tap "Run Patrol E2E Suite" to execute integration telemetry.', style: TextStyle(color: Colors.white54, fontSize: 12)),
                  )
                : ListView.builder(
                    itemCount: _traceLogs.length,
                    itemBuilder: (context, i) => Padding(
                      padding: const EdgeInsets.symmetric(vertical: 3.0),
                      child: Text(_traceLogs[i], style: const TextStyle(color: Colors.greenAccent, fontSize: 11, fontFamily: 'monospace')),
                    ),
                  ),
          ),
        ],
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Multi-Step Checkout Flow (`E2ECheckoutFlow`)**:
   Represents an enterprise customer journey spanning catalog inspection, native OS shipping permissions, payment selection, and confirmation.
2. **Handling Native OS Boundaries with Patrol**:
   Step 1 demonstrates the fundamental limitation of standard tests and how Patrol's native automator (`$.native.grantPermissionWhenInUse()`) bridges to iOS/Android system permission dialogs.
3. **Deterministic End-to-End Verification**:
   The test runner traces the entire customer funnel from initial app boot to receipt generation, verifying that all system components (navigation, state, and permissions) function synchronously on compiled native binaries.
